html:
{#- Participação — reproduces the paper form (XSS_OP.FR.006). Logo = Empresa Padrão's
    Company logo; footer code + local from SIGOS Settings (Documentos Impressos). -#}
{%- set empresa = frappe.db.get_single_value("SIGOS Settings", "empresa_padrao") or frappe.db.get_single_value("Global Defaults", "default_company") -%}
{%- set logo = frappe.db.get_value("Company", empresa, "company_logo") if empresa else None -%}
{%- set codigo = frappe.db.get_single_value("SIGOS Settings", "codigo_formulario_participacao") or "" -%}
{%- set local = frappe.db.get_single_value("SIGOS Settings", "local_documentos") or doc.delegacao or "" -%}
{%- set tipos_db = frappe.get_all("Tipo De Infracao", filters={"ativo": 1}, fields=["name", "ordem"], order_by="ordem asc, name asc") -%}
{%- set marcadas = doc.infracoes | map(attribute="tipo_de_infracao") | list -%}
{%- set ordenadas = (tipos_db | selectattr("ordem") | map(attribute="name") | list) + (tipos_db | rejectattr("ordem") | map(attribute="name") | list) -%}
{%- set todas = ordenadas + (marcadas | reject("in", ordenadas) | list) -%}
{%- set metade = ((todas | length) + 1) // 2 -%}
{%- set meses = ["Janeiro", "Fevereiro", "Março", "Abril", "Maio", "Junho", "Julho", "Agosto", "Setembro", "Outubro", "Novembro", "Dezembro"] -%}
{%- set d = frappe.utils.getdate(doc.data) if doc.data else None -%}
{%- set testemunhas = doc.tabela_testemunhas or [] -%}
<style>
	@page { size: A4 portrait; margin: 12mm 14mm; }
	.pf { font-family: "Times New Roman", Times, serif; color: #111; font-size: 11.5px; }
	.pf * { box-sizing: border-box; }
	.pf-logo { height: 62px; margin: 0 0 14px 28px; }
	.pf-logo img { max-height: 62px; max-width: 170px; }
	.pf-title { border: 1px solid #333; border-left: none; border-right: none; text-align: center;
		font-size: 14px; letter-spacing: .04em; padding: 9px 0 16px; margin-bottom: 14px; }
	.pf-title small { display: block; font-size: 9px; color: #666; letter-spacing: 0; margin-top: 2px; }
	.pf-lbl { font-size: 11px; text-transform: uppercase; margin: 12px 0 2px 24px; }
	.pf-tb { width: 100%; border-collapse: collapse; }
	.pf-tb td { border: 1px solid #333; padding: 3px 6px; height: 20px; vertical-align: middle; }
	.pf-k { text-transform: uppercase; font-size: 10.5px; white-space: nowrap; }
	.pf-v { font-family: "Courier New", Courier, monospace; font-size: 12px; font-weight: bold; }
	.pf-caps { text-transform: uppercase; }
	.pf-chk td { height: 17px; padding: 1px 6px; font-size: 10.5px; text-transform: uppercase; }
	.pf-chk td.mk { width: 46px; text-align: center; font-family: "Courier New", monospace; font-weight: bold; font-size: 13px; }
	.pf-chk td.gap { border-top: none; border-bottom: none; width: 8px; padding: 0; }
	.pf-rel { border: 1px solid #333; padding: 4px 8px 8px; }
	.pf-rel-top { font-size: 10.5px; text-transform: uppercase; margin-bottom: 4px; }
	.pf-rel-top span { display: inline-block; margin-right: 26px; }
	.pf-rel-top b { font-family: "Courier New", Courier, monospace; font-size: 12px; text-transform: none; }
	.pf-rep { min-height: 150px; line-height: 21px; white-space: pre-wrap; font-family: "Courier New", Courier, monospace;
		font-size: 12px; border-bottom: 1px dotted #999; }
	.pf-rep-k { text-transform: uppercase; font-size: 10.5px; font-family: "Times New Roman", Times, serif; }
	.pf-outras { margin-top: 4px; font-size: 10.5px; }
	.pf-sig td { height: 46px; vertical-align: top; font-size: 10.5px; }
	.pf-sig .nm { display: block; margin-top: 16px; font-family: "Courier New", Courier, monospace; font-size: 11px; }
	.pf-local { text-align: center; text-transform: uppercase; margin: 8px 0 0; font-size: 11px; }
	.pf-local b { font-family: "Courier New", Courier, monospace; text-transform: none; font-size: 12px; }
	.pf-foot { margin-top: 70px; font-size: 9.5px; }
	.pf-foot .own { text-align: center; font-style: italic; margin-bottom: 14px; }
	.pf-foot .cod { font-family: Arial, Helvetica, sans-serif; font-size: 10.5px; line-height: 15px; white-space: pre-line; }
	.pf-ref { font-size: 8.5px; color: #777; text-align: right; margin-top: 4px; }
</style>
<div class="pf">
	<div class="pf-logo">{% if logo %}<img src="{{ logo }}">{% endif %}</div>

	<div class="pf-title">PARTICIPAÇÃO{% if doc.docstatus == 0 %}<small>RASCUNHO — não submetida</small>{% elif doc.docstatus == 2 %}<small>CANCELADA</small>{% endif %}</div>

	<div class="pf-lbl">O Participante:</div>
	<table class="pf-tb"><tr>
		<td class="pf-k" style="width:11%">Número</td><td class="pf-v" style="width:14%">{{ doc.participante_numero or "" }}</td>
		<td class="pf-k" style="width:7%">Cat</td><td class="pf-v" style="width:14%">{{ doc.participante_categoria or "" }}</td>
		<td class="pf-k" style="width:8%">Nome</td><td class="pf-v">{{ doc.participante_nome or "" }}</td>
	</tr></table>

	<div class="pf-lbl">O Infractor (escrever em letras maiúsculas)</div>
	<table class="pf-tb"><tr>
		<td class="pf-k" style="width:11%">Número</td><td class="pf-v" style="width:14%">{{ doc.mecanografico or "" }}</td>
		<td class="pf-k" style="width:7%">Cat</td><td class="pf-v" style="width:14%">{{ doc.categoria or "" }}</td>
		<td class="pf-k" style="width:8%">Nome</td><td class="pf-v pf-caps">{{ doc.nome_do_vigilante or doc.vigilante or "" }}</td>
	</tr></table>

	<div class="pf-lbl">Tipo de Infração:</div>
	<table class="pf-tb pf-chk">
		{%- for i in range(metade) %}
		{%- set a = todas[i] %}
		{%- set b = todas[i + metade] if (i + metade) < (todas | length) else None %}
		<tr>
			<td>{{ a }}</td><td class="mk">{{ "X" if a in marcadas else "" }}</td>
			<td class="gap"></td>
			<td>{{ b or "" }}</td><td class="mk">{{ "X" if (b and b in marcadas) else "" }}</td>
		</tr>
		{%- endfor %}
	</table>
	{%- if doc.outras_descricao %}<div class="pf-outras"><b>Outras:</b> {{ doc.outras_descricao }}</div>{% endif %}

	<div class="pf-lbl">Relatório</div>
	<div class="pf-rel">
		<div class="pf-rel-top">
			<span>Posto: <b>{{ doc.posto_nome or doc.posto or "" }}</b></span>
			<span>Horas: <b>{{ doc.horas or "" }}</b></span>
			<span>Data: <b>{{ d.strftime("%d.%m.%Y") if d else "" }}</b></span>
		</div>
		<div class="pf-rep"><span class="pf-rep-k">Reportagem: </span>{{ doc.relato or "" }}</div>
	</div>

	<div class="pf-lbl">Do facto foram testemunhas:</div>
	<table class="pf-tb">
		{%- for t in testemunhas %}
		<tr>
			<td class="pf-k" style="width:11%">Número</td><td class="pf-v" style="width:14%">{{ t.numero or "" }}</td>
			<td class="pf-k" style="width:7%">Cat</td><td class="pf-v" style="width:14%">{{ t.categoria or "" }}</td>
			<td class="pf-k" style="width:8%">Nome</td><td class="pf-v">{{ t.nome or "" }}</td>
		</tr>
		{%- endfor %}
		{%- for i in range([2 - (testemunhas | length), 0] | max) %}
		<tr>
			<td class="pf-k" style="width:11%">Número</td><td style="width:14%"></td>
			<td class="pf-k" style="width:7%">Cat</td><td style="width:14%"></td>
			<td class="pf-k" style="width:8%">Nome</td><td class="pf-v">{{ doc.testemunhas if (i == 0 and not testemunhas and doc.testemunhas) else "" }}</td>
		</tr>
		{%- endfor %}
	</table>

	<table class="pf-tb pf-sig" style="margin-top:16px"><tr>
		<td style="width:50%">O Participante<br>ASS:<span class="nm">{{ doc.participante_nome or "" }}</span></td>
		<td>O Infractor<br>ASS:<span class="nm">{{ doc.nome_do_vigilante or "" }}</span></td>
	</tr></table>
	<div class="pf-local">{{ (local or "____________") | upper }}, aos <b>{{ "%02d" | format(d.day) if d else "____" }}</b> de <b>{{ meses[d.month - 1] if d else "______________" }}</b> de <b>{{ d.year if d else "20__" }}</b></div>

	<div class="pf-foot">
		{%- if empresa %}<div class="own">Este documento é propriedade da {{ empresa | upper }}. Não é permitida sua reprodução sem autorização.<br>Depois de impresso este documento é considerado cópia não controlada</div>{% endif %}
		{%- if codigo %}<div class="cod">{{ codigo | e }}</div>{% endif %}
		<div class="pf-ref">{{ doc.name }}{% if doc.gravidade %} · Gravidade {{ doc.gravidade }}{% endif %}</div>
	</div>
</div>
